mapper.select:
SELECT /* kr.or.kids.domain.cm.community.board.mapper.selectBoardList */ A.pst_sn AS pstSn , A.bbs_id AS bbsId , A.pst_ttl AS pstTtl , A.pst_cn AS pstCn , A.pst_inq_cnt AS pstInqCnt , A.pst_kogl_cprgt_type_cd AS pstKoglCprgtTypeCd , A.atch_file_group_id AS atchFileGroupId , A.thmb_id AS thmbId , A.fix_yn AS fixYn , CASE WHEN A.fix_yn = 'Y' THEN A.fix_bgng_ymd ELSE NULL END AS fixBgngYmd , CASE WHEN A.fix_yn = 'Y' THEN A.fix_end_ymd ELSE NULL END AS fixEndYmd , A.vdo_url_addr AS vdoUrlAddr , A.expsr_yn AS expsrYn , A.wrtr_dept_nm AS wrtrDeptNm , A.mdfr_dept_nm AS mdfrDeptNm , A.rgtr_id AS rgtrId , TO_CHAR(A.reg_dt, 'YYYY.MM.DD') AS regDt , A.mdfr_id AS mdfrId , TO_CHAR(A.mdfcn_dt, 'YYYY.MM.DD') AS mdfcnDt , CASE WHEN EXISTS ( SELECT 1 FROM kids_own.tb_cm_m_file_uld U INNER JOIN kids_own.tb_ca_e_file_trsm F ON U.atch_file_id = F.atch_file_group_id WHERE U.pst_sn = A.pst_sn AND U.del_yn = 'N' AND U.uld_task_se_cd = '06' AND U.file_se_cd = '09' ) THEN 'Y' ELSE 'N' END AS hasFile FROM kids_own.tb_pp_m_pst A WHERE 1=1 AND A.bbs_id = #{bbsId}
AND A.pst_ttl LIKE '%' || #{searchKeyword} || '%'
AND A.rgtr_id IN ( SELECT m.mbr_no FROM kids_own.tb_pp_m_mbr_info m WHERE m.encpt_mbr_flnm = #{encryptedWriterKeyword} )
AND A.rgtr_id IN ( SELECT ei.emp_no FROM kids_own.tb_pp_m_emp_info ei WHERE ei.emp_nm LIKE '%' || #{searchKeyword} || '%' )
AND A.pst_cn LIKE '%' || #{searchKeyword} || '%'
ORDER BY CASE WHEN A.fix_yn = 'Y' AND A.fix_bgng_ymd <= TO_CHAR(NOW(), 'YYYYMMDD') AND A.fix_end_ymd >= TO_CHAR(NOW(), 'YYYYMMDD') THEN 0 ELSE 1 END ASC , A.pst_sn DESC LIMIT #{pageSize} OFFSET (#{page} - 1) * #{pageSize}

mapper.update:
/* kr.or.kids.domain.cm.community.board.mapper.updateBoard */
UPDATE kids_own.tb_pp_m_pst


        pst_ttl = #{pstTtl}




            ,

        pst_cn = #{pstCn}



        , pst_kogl_cprgt_type_cd = #{pstKoglCprgtTypeCd}



        , atch_file_group_id = #{atchFileGroupId}



        , thmb_id = #{thmbId}



        , fix_yn = #{fixYn}



        , fix_bgng_ymd = #{fixBgngYmd}



        , fix_end_ymd = #{fixEndYmd}



        , vdo_url_addr = #{vdoUrlAddr}



        , expsr_yn = #{expsrYn}



        , mdfr_dept_nm = #{mdfrDeptNm}



        , mdfr_id = #{mdfrId}



        , thmb_expln_cn = #{thmbExplnCn}



        , vdo_expln_cn = #{vdoExplnCn}


    , mdfcn_dt = NOW()

WHERE pst_sn = #{pstSn}

/* kr.or.kids.domain.cm.community.board.mapper.updateBoardViewCount */
UPDATE kids_own.tb_pp_m_pst
   SET pst_inq_cnt = COALESCE(pst_inq_cnt, 0) + 1
     , mdfcn_dt = NOW()
 WHERE pst_sn = #{pstSn}

UPDATE kids_own.TB_CM_M_ASMT_CMNT
   SET cmnt_dtl_cn = #{cmntDtlCn},
       mdfr_id     = #{mdfrId},
       mdfcn_dt    = #{mdfcnDt}
 WHERE asmt_cmnt_sn = #{asmtCmntSn}
   AND (del_yn IS NULL OR del_yn = 'N')

mapper.select:
SELECT COALESCE(MAX(cmnt_ans_sn), 0) + 1
  FROM kids_own.TB_CM_M_ASMT_CMNT
 WHERE asmt_sn = #{pstSn}
   AND bbs_id  = #{bbsId}
   AND (del_yn IS NULL OR del_yn = 'N')
   AND (
       (#{orgnlUpCmntAnsSn,jdbcType=NUMERIC} IS NULL AND orgnl_up_cmnt_ans_sn IS NULL)
       OR orgnl_up_cmnt_ans_sn = #{orgnlUpCmntAnsSn,jdbcType=NUMERIC}
   )
